// LINKEDIN DAILY — CONFIG
// Edit values only in this node. Nothing else in either workflow needs changing.
// Both workflows carry an identical copy of this node; change one, change the other.
//
// Any key left blank means that step is SKIPPED, not that the run fails. That is what
// lets the whole pipeline be demonstrated on a screen-share before a single credential
// exists — see LOOM.md.

// ---------------------------------------------------------------- The content sheet
// The id is the long code in the sheet's web address:
// docs.google.com/spreadsheets/d/<THIS BIT>/edit
//
// Blank -> the DEMO_BANK posts below are used instead and nothing is logged. The draft is
// still written, rendered and delivered, so the pipeline can be watched end to end with no
// Google account attached at all.
const SHEET_ID = '';
const BANK_TAB = 'Bank';   // one row per post, in publish order. sheet/Bank.csv
const LOG_TAB  = 'Log';    // append-only outcome log. sheet/Log.csv

// Column headings, exactly as they appear in row 1 of each tab.
const BANK_COLUMNS = {
  slot:          'Slot',
  slug:          'Slug',
  pillar:        'Pillar',
  category:      'Category',
  headline:      'Headline',
  headline_size: 'Headline size',
  subhead:       'Subhead',
  layout:        'Layout',
  items:         'Items',        // JSON array — shape depends on Layout
  band:          'Band',         // grid only
  stat_big:      'Stat big',     // stat only
  stat_sub:      'Stat sub',     // stat only
  footer:        'Footer',
  caption:       'Caption',      // blank -> written by the model, if one is configured
  state:         'State'         // ready | posted | cancelled | holding
};

// Append-only. A draft is opened by an `awaiting` row and closed by a later row carrying the
// same Message id: posted | cancelled | expired | superseded | failed. Three statuses annotate
// without closing: edit-refused | alert | report. The full rule is in "find the pending draft".
const LOG_COLUMNS = {
  date:       'Date',
  slug:       'Slug',
  slot:       'Slot',
  status:     'Status',
  channel_id: 'Channel id',
  message_id: 'Message id',   // the Discord draft — how workflow 02 finds the reply
  reply_id:   'Reply id',     // the reviewer message that caused this row, so it is acted on once
  caption_fp: 'Caption fp',   // fingerprint of the delivered caption
  pillar:     'Pillar',       // what topic rotation is measured against
  hook:       'Hook',         // the opening sentence, for the repeated-hook check
  urn:        'Post urn',
  note:       'Note',
  at:         'At'
};

// Only these bank states are drafted. Anything else is treated as already handled.
const READY_STATES = ['', 'ready'];

// ---------------------------------------------------------------- When it runs
// The schedule lives on the trigger node, not here — this is the guard that stops a manual
// run at 11pm on a Sunday from putting a post out on a day it should not.
// 1 = Monday ... 7 = Sunday.
const PUBLISH_DAYS = [1, 2, 3, 4, 5];
const TIMEZONE     = 'Asia/Singapore';

// Design-side posts go out on Thursdays. build.js in the design repo enforces this at build
// time; this is the same rule enforced again at publish time, because the bank can be
// reordered in the sheet long after it was built.
const DESIGN_PILLAR_PREFIX     = 'Design process';
const ENFORCE_DESIGN_THURSDAY  = true;
const OFF_CADENCE_DESIGN_SLOTS = [6];   // slot 6 is a Friday, and went out that way on purpose

// No two posts published within this many slots may share a layout or a pillar. Five is a
// publishing week at the weekday cadence. Measured in slots, not dates.
const WINDOW_SLOTS = 5;

// Topic rotation, measured in CALENDAR DAYS from the log rather than in slots, so it still
// holds after the bank has been reordered, rows were skipped or a post went out by hand.
//   TOPIC_COOLDOWN_DAYS  a pillar published this recently is held; the next row is tried
//   FAMILY_MAX_PER_WEEK  at most this many posts in any rolling 7 days from one pillar family
//                        (the part before the comma: "AI workflow, reporting" -> "AI workflow")
const TOPIC_COOLDOWN_DAYS = 21;
const FAMILY_MAX_PER_WEEK = 2;

// ---------------------------------------------------------------- Brand system
// DESIGN.md is the source of record for all of this. Changing a colour here changes every
// future render; it does not reflow anything already published.
const BRAND = {
  bg:          '#050505',
  accent:      '#DC2056',
  white:       '#FFFFFF',
  muted:       '#A8A8A8',
  line:        '#303030',
  card_border: '#262626',
  card_bg:     '#0B0B0B',
  font:        'Arial, Helvetica, sans-serif',
  site:        'example.com'
};

const CANVAS_WIDTH  = 1080;
const CANVAS_HEIGHT = 1350;
const DEVICE_SCALE  = 2;      // 2 -> a 2160x2700 PNG from a 1080x1350 canvas

// The wordmark, inlined into the template. The renderer loads the HTML with no network, so
// nothing here may reference a file or a URL. Paste the contents of your_logo.svg
// (white wordmark, pink mark) between the quotes. Left blank the template falls back to a
// plain text wordmark, which is visibly not the logo — on purpose. A missing logo must look
// missing rather than quietly pass review.
const LOGO_SVG = '';

// ---------------------------------------------------------------- The renderer
// HTML -> PNG. n8n has no browser of its own, so this is one HTTP call out.
//
//   'browserless' — self-hosted, and the one to use. Add it to the same docker-compose file
//                   n8n runs in and point RENDER_URL at http://browserless:3000. Returns
//                   the PNG bytes directly.
//   'hcti'        — htmlcsstoimage.com. RENDER_USER / RENDER_KEY are the API id and key.
//                   Returns a JSON url, which the workflow then downloads.
//   ''            -> no image. The run stops at "STOP: renderer not configured" and delivers
//                    nothing, because a caption without its image is not a draft.
const RENDER_PROVIDER = 'browserless';
const RENDER_URL      = 'http://browserless:3000';
const RENDER_USER     = '';   // hcti only
const RENDER_KEY      = '';   // browserless token, or the hcti api key

// A render that comes back under this many bytes is a blank or half-drawn canvas, not a
// post. Measured against the live bank: the smallest real render is about 87 KB.
const MIN_PNG_BYTES = 40000;

// ---------------------------------------------------------------- Discord approval
// The channel the draft is delivered to, and the only place an approval is read from.
//
// ANYONE WHO CAN SEND A MESSAGE IN THIS CHANNEL CAN PUBLISH TO THE COMPANY PAGE. Use a
// private channel created for this and nothing else — not a general channel, where one
// person typing a common English word publishes a draft.
//
// The bot token goes in an n8n Discord credential, not here.
const DISCORD_CHANNEL_ID = '';

// What a reviewer types. Matched case-insensitively against the whole message, trimmed.
// Trailing text is NOT tolerated: "post" approves, "post please" does not, because the
// looser the match the more ways an unrelated sentence becomes a publish.
const APPROVE_WORDS = ['post', 'approve', 'ship it'];
const CANCEL_WORDS  = ['cancel', 'reject', 'discard'];

// An EDIT is a message whose FIRST LINE is one of these words and whose remaining lines are the
// replacement caption. It is never published directly: it is checked against the same caption
// rules, and if it passes the bot re-delivers it with the same image as a NEW draft that needs
// its own `post`. If it fails, the bot replies with the reasons and the original stays open.
const EDIT_WORDS = ['edit'];

// The line appended under every draft. Workflow 02 strips exactly this string back off before
// fingerprinting, so change it only while no draft is awaiting approval.
const APPROVAL_INSTRUCTION = 'Reply **post** to publish, **cancel** to discard, or **edit** '
  + 'with the new caption on the lines below it.';

// How long a draft stays approvable. After this the day has moved on and the claims in it
// may not have. Workflow 02 marks it expired rather than publishing it.
const APPROVAL_EXPIRES_HOURS = 20;

// When LinkedIn rejects the token on an approved draft, the approval channel is told once, then
// again only after this many hours, not every five minutes for the rest of the day.
const ALERT_REPEAT_HOURS = 6;

// ---------------------------------------------------------------- LinkedIn
// The organisation to post as, and the token that may post as it.
// urn:li:organization:<id> — the id is in the page's admin URL.
const LINKEDIN_ORG_URN = 'urn:li:organization:0000000';

// A w_organization_social token. Blank -> nothing is ever published, whatever a reviewer
// replies; the run reaches "STOP: not published" and says why.
const LINKEDIN_ACCESS_TOKEN = '';

// Probed 2026-08-18: 202512 and earlier are retired (HTTP 426 NONEXISTENT_VERSION).
// 202601..202608 are active.
const LINKEDIN_VERSION = '202608';

// LinkedIn access tokens last 60 days and lapse silently. Put the current token's expiry date
// here (YYYY-MM-DD) and every run summary warns TOKEN_WARN_DAYS ahead. Blank -> no early
// warning; an expired token is still caught at publish time and alerted, never failed quietly.
const LINKEDIN_TOKEN_EXPIRES_ON = '';
const TOKEN_WARN_DAYS = 7;

// Weekly report, built from the Log by workflow 02 the first time its poll runs on
// REPORT_WEEKDAY at or after REPORT_HOUR (TIMEZONE). Posted to REPORT_WEBHOOK_URL.
const REPORT_WEEKDAY = 1;   // 1 = Monday
const REPORT_HOUR    = 9;

// Per-post impressions, clicks and reactions in the weekly report. Needs a token with
// r_organization_social, which LinkedIn only grants to apps approved for the Community
// Management API. false -> the report is built from the Log alone. A 403 is reported as that
// product gate, not as a failure.
const STATS_ENABLED = false;

// ---------------------------------------------------------------- Writing the caption
// Only used for a bank row whose Caption cell is empty. A row that already carries a caption
// is delivered as written — the model never rewrites approved copy.
//
// Blank key -> a row with no caption is held back with a reason, never delivered bare.
const LLM_BASE_URL = 'https://llm.example.com';
const LLM_API_KEY  = '';
const LLM_MODEL    = 'modelark/seed-2-0-pro-260328';

// The caption rules, from the house content guide. These are handed to the model
// and are also checked in code afterwards, because a model asked for 220 words will
// sometimes write 340 and say it wrote 220.
const CAPTION_MIN_WORDS = 120;
const CAPTION_MAX_WORDS = 220;
const HASHTAGS_MIN      = 4;
const HASHTAGS_MAX      = 6;
const MAX_EMOJI         = 1;
const HASHTAGS_LAST_LINE_ONLY = true;   // hashtags mid-caption read as spam
const NO_LINKS_IN_BODY        = true;   // a link in the body cuts reach; it goes in the first comment

// The opening sentence is compared with every hook published in the last HOOK_LOOKBACK_DAYS.
// At or above HOOK_SIMILARITY (share of meaningful words in common) it is held as a repeat.
const HOOK_LOOKBACK_DAYS = 60;
const HOOK_SIMILARITY    = 0.6;

// A MODEL-written caption that fails the rules gets this many rewrites, with the exact failures
// fed back to the model. Still failing -> held for a human. A banked caption is never
// rewritten: a person wrote it, so a person fixes it. 0 -> no rewrite, hold straight away.
const REWRITE_ATTEMPTS = 1;

// Rejected outright, in a written caption or a banked one. A caption that trips this is held
// back with the phrase named, never quietly edited.
const BANNED_PHRASES = [
  'game changer', 'game-changer', 'revolutionary', 'the future is here',
  'cutting edge', 'cutting-edge', 'unlock the power', 'next level',
  'fast-paced world', 'seamlessly', 'synergy', 'paradigm shift',
  'thought leader', 'disrupt', 'skyrocket', 'supercharge',
  'best-in-class', 'world-class', 'leverage our'
];

// Discord's hard limit on one message is 2000 characters. The caption travels in the message
// body so the reviewer reads exactly what would be published.
const DISCORD_MESSAGE_LIMIT = 2000;

// ---------------------------------------------------------------- Optional notification
const REPORT_WEBHOOK_URL = '';   // Slack incoming webhook. Blank = no notification.

// Workflow 02 demo: with SHEET_ID blank it reads a made-up log holding one open draft and a
// made-up channel holding this reply to it, so the approval gate runs with no Discord bot.
// 'post' | 'cancel' | 'edit' (a clean revision) | 'bad-edit' (one the caption rules refuse)
const DEMO_REPLY = 'edit';

// ---------------------------------------------------------------- Demo bank
// Used only when SHEET_ID is blank. Three posts, three layouts. With the demo log ("load the
// demo log") slot 1 is held by topic rotation, so slot 2 is picked and goes through the
// write -> fail -> rewrite -> pass loop. While the demo bank is in use the run is FORCED into
// preview: made-up content can never reach the company page.
const DEMO_BANK = [
  {
    slot: 1, slug: 'demo-map-the-failure-mode', pillar: 'Engineering insight',
    category: 'RESILIENCE',
    headline: 'ONE OUTAGE.<br>HOW MANY<br><em>BLOCKED TEAMS</em>?',
    headline_size: 94,
    subhead: 'A dependency you never wrote down is still a dependency.',
    layout: 'timeline',
    items: [
      ['Ship a hotfix', 'Without the pipeline, what is your deploy path?'],
      ['Authenticate', 'If SSO is down, who can still get in?'],
      ['Build artifacts', 'Do they exist anywhere other than there?'],
      ['Your assistant', 'Work stopped, or just slower?']
    ],
    footer: 'Map the failure mode first.',
    caption: 'Most teams can name the tools they depend on. Far fewer can say what still '
      + 'works when one of them is down for a day.\n\n'
      + 'Before the next outage, sit down with whoever ships your releases and walk through '
      + 'four questions. Could you deploy a fix without the pipeline? Could anyone sign in if '
      + 'single sign-on was down? Do your build outputs exist anywhere else? And when the '
      + 'assistant everyone leans on stops answering, does work stop or just slow down?\n\n'
      + 'None of this needs new software. It needs an afternoon and a written answer to each '
      + 'question, kept somewhere people will actually find it.\n\n'
      + 'The trade-off is real: an answer you wrote down goes stale as the stack changes, so '
      + 'it needs an owner and a review date, or it quietly becomes fiction.\n\n'
      + 'Which of the four would your team struggle with first?\n\n'
      + '(Demo draft, not for publication.)\n\n'
      + '#Resilience #DevOps #Engineering #Demo'
  },
  {
    slot: 2, slug: 'demo-never-approve-your-own-work',
    pillar: 'Production AI guardrails', category: 'AI GUARDRAILS',
    headline: 'NEVER APPROVE<br><em>YOUR OWN WORK</em>.',
    headline_size: 90,
    subhead: 'Four things a workflow must never read as a human saying yes.',
    layout: 'grid',
    items: [
      ['Its own message', 'The draft it just posted for review'],
      ['Another bot', 'A second agent is not a second opinion'],
      ['Silence', 'Nobody objected is not anybody approved'],
      ['A reaction', 'A thumbs-up is not a signature']
    ],
    band: 'APPROVAL IS A HUMAN, IN THE RIGHT CHANNEL.',
    footer: 'Everything else is the system agreeing with itself.',
    // Blank on purpose: in the demo this row is written by "demo writer - first draft", whose
    // caption breaks four rules, then fixed by "demo writer - rewrite" — the real rewrite loop,
    // with canned model answers standing in for an API key.
    caption: ''
  },
  {
    slot: 3, slug: 'demo-reporting-costs-a-day', pillar: 'AI workflow, reporting',
    category: 'REPORTING',
    headline: 'IT ISN’T ANALYSIS.<br>IT’S <em>COLLECTION</em>.',
    headline_size: 92,
    subhead: 'A day of assembling. Four minutes of reading.',
    layout: 'cards',
    items: [
      ['STEP 01 · COLLECT', 'Numbers<br>assemble', 'Exports and systems pulled on a schedule.'],
      ['STEP 02 · RECONCILE', 'Conflicts<br>surface', 'Sources that disagree get flagged, never averaged.'],
      ['STEP 03 · DECIDE', 'Stays<br>human', 'Someone still decides which system is right.']
    ],
    footer: 'The judgement stays. The copying goes.',
    caption: 'The weekly report is rarely slow because of the analysis. It is slow because '
      + 'somebody spends most of a day collecting numbers from five places first.\n\n'
      + 'That collecting is the part worth automating. Pull each export on a schedule, line '
      + 'the figures up, and flag the sources that disagree instead of averaging them away. '
      + 'The person who used to assemble the report now starts the morning with a finished '
      + 'draft and a short list of conflicts to settle.\n\n'
      + 'What does not change is the judgement. When two systems disagree about revenue, a '
      + 'person still decides which one is right, and the report says so.\n\n'
      + 'The limit worth knowing: this only works once the sources have stable exports. If '
      + 'a number lives in somebody\'s head, it has to be written down first.\n\n'
      + 'How many hours does your team spend collecting before anyone analyses anything?\n\n'
      + '(Demo draft, not for publication.)\n\n'
      + '#Reporting #Automation #Operations #Demo'
  }
];

// ---------------------------------------------------------------- Safety switch
//   TEST_RUN true,  TEST_CHANNEL_ID blank -> PREVIEW. The draft is written and rendered so
//                                            you can look at the PNG, but it is delivered
//                                            nowhere and published nowhere. Ships this way.
//   TEST_RUN true,  TEST_CHANNEL_ID set   -> TEST. The draft really is delivered, to that
//                                            channel instead of the live one, and approvals
//                                            are read there. LinkedIn is still never
//                                            published to.
//   TEST_RUN false                        -> LIVE. Delivered to DISCORD_CHANNEL_ID, and an
//                                            approval there publishes to the company page.
//
// Filling in TEST_CHANNEL_ID can only ever redirect a delivery. It cannot cause a publish —
// going live is the separate, deliberate act of setting TEST_RUN = false.
const TEST_RUN        = true;
const TEST_CHANNEL_ID = '';

// Hard ceiling on posts published per run. One a day is the whole design; this exists so a
// bad batch of rows cannot become a bad batch of posts.
const DAILY_CAP = 1;

// ---------------------------------------------------------------- derived
const USING_DEMO_BANK = SHEET_ID.trim() === '';

let MODE = TEST_RUN !== true ? 'live'
  : (TEST_CHANNEL_ID.trim() !== '' ? 'test' : 'preview');

// Demo content is not a post. It cannot open the publish gate, whatever TEST_RUN says.
const FORCED_PREVIEW = USING_DEMO_BANK && MODE === 'live';
if (FORCED_PREVIEW) MODE = 'preview';

const CHANNEL_ID = MODE === 'test' ? TEST_CHANNEL_ID.trim() : DISCORD_CHANNEL_ID.trim();

const lower = (a) => a.map((s) => String(s).trim().toLowerCase()).filter(Boolean);

const TOKEN_EXPIRY_MS = Date.parse(String(LINKEDIN_TOKEN_EXPIRES_ON).trim() + 'T00:00:00Z');
const TOKEN_DAYS_LEFT = isNaN(TOKEN_EXPIRY_MS) ? null
  : Math.floor((TOKEN_EXPIRY_MS - Date.now()) / 86400000);

return [{
  json: {
    sheet_id: SHEET_ID.trim(),
    bank_tab: BANK_TAB,
    log_tab:  LOG_TAB,
    bank_columns: BANK_COLUMNS,
    log_columns:  LOG_COLUMNS,
    ready_states: READY_STATES.map((s) => String(s).trim().toLowerCase()),

    publish_days: PUBLISH_DAYS.map(Number),
    timezone:     TIMEZONE,

    design_pillar_prefix:     DESIGN_PILLAR_PREFIX,
    enforce_design_thursday:  ENFORCE_DESIGN_THURSDAY !== false,
    off_cadence_design_slots: OFF_CADENCE_DESIGN_SLOTS.map(Number),
    window_slots:             Number(WINDOW_SLOTS) || 5,
    topic_cooldown_days:      Number(TOPIC_COOLDOWN_DAYS) || 0,
    family_max_per_week:      Number(FAMILY_MAX_PER_WEEK) || 0,

    brand:         BRAND,
    canvas_width:  Number(CANVAS_WIDTH) || 1080,
    canvas_height: Number(CANVAS_HEIGHT) || 1350,
    device_scale:  Number(DEVICE_SCALE) || 1,
    logo_svg:      LOGO_SVG,

    render_provider: RENDER_PROVIDER.trim().toLowerCase(),
    render_url:      RENDER_URL.replace(/\/+$/, ''),
    render_user:     RENDER_USER.trim(),
    render_key:      RENDER_KEY.trim(),
    min_png_bytes:   Number(MIN_PNG_BYTES) || 0,

    channel_id:     CHANNEL_ID,
    approve_words:  lower(APPROVE_WORDS),
    cancel_words:   lower(CANCEL_WORDS),
    edit_words:     lower(EDIT_WORDS),
    approval_instruction: APPROVAL_INSTRUCTION,
    alert_repeat_hours:   Number(ALERT_REPEAT_HOURS) || 6,
    approval_expires_hours: Number(APPROVAL_EXPIRES_HOURS) || 20,
    discord_message_limit:  Number(DISCORD_MESSAGE_LIMIT) || 2000,

    linkedin_org_urn: LINKEDIN_ORG_URN.trim(),
    linkedin_token:   LINKEDIN_ACCESS_TOKEN.trim(),
    linkedin_version: LINKEDIN_VERSION,
    linkedin_token_days_left: TOKEN_DAYS_LEFT,
    token_warn_days:  Number(TOKEN_WARN_DAYS) || 7,
    report_weekday:   Number(REPORT_WEEKDAY) || 1,
    report_hour:      Number(REPORT_HOUR) || 0,

    llm_base_url: LLM_BASE_URL.replace(/\/+$/, ''),
    llm_api_key:  LLM_API_KEY.trim(),
    llm_model:    LLM_MODEL,

    caption_min_words: Number(CAPTION_MIN_WORDS) || 0,
    caption_max_words: Number(CAPTION_MAX_WORDS) || 400,
    hashtags_min:      Number(HASHTAGS_MIN) || 0,
    hashtags_max:      Number(HASHTAGS_MAX) || 6,
    max_emoji:         Number(MAX_EMOJI) || 0,
    banned_phrases:    lower(BANNED_PHRASES),
    hashtags_last_line_only: HASHTAGS_LAST_LINE_ONLY !== false,
    no_links_in_body:   NO_LINKS_IN_BODY !== false,
    hook_lookback_days: Number(HOOK_LOOKBACK_DAYS) || 60,
    hook_similarity:    Number(HOOK_SIMILARITY) || 0.6,
    rewrite_attempts:   Math.max(0, Number(REWRITE_ATTEMPTS) || 0),

    report_webhook_url: REPORT_WEBHOOK_URL.trim(),
    demo_bank:          DEMO_BANK,
    demo_reply:         String(DEMO_REPLY).trim().toLowerCase(),
    daily_cap:          Number(DAILY_CAP) || 1,

    // derived flags — every gate reads these, never the raw constants
    mode:            MODE,
    preview_only:    MODE === 'preview',
    test_delivery:   MODE === 'test',
    live_publish:    MODE === 'live' && LINKEDIN_ACCESS_TOKEN.trim() !== '',
    sheet_enabled:   SHEET_ID.trim() !== '',
    using_demo_bank: USING_DEMO_BANK,
    forced_preview:  FORCED_PREVIEW,
    render_enabled:  RENDER_PROVIDER.trim() !== '' && RENDER_URL.trim() !== '',
    deliver_enabled: MODE !== 'preview' && CHANNEL_ID !== '',
    llm_enabled:     LLM_API_KEY.trim() !== '',
    report_enabled:  REPORT_WEBHOOK_URL.trim() !== '',
    stats_enabled:   STATS_ENABLED === true && LINKEDIN_ACCESS_TOKEN.trim() !== '' && !USING_DEMO_BANK,
    logo_present:    LOGO_SVG.trim() !== ''
  }
}];

// The log, when there is no sheet. SHEET_ID is blank, so this stands in for the Log tab.
//
// Two days of history, shaped exactly as the sheet returns them: one post that was drafted and
// published two days ago. It is there so the two date-based checks have something to bite on
// in a demo:
//
//   * topic rotation  its pillar is "Engineering insight", the same as demo slot 1, so slot 1
//                     is held (published 2 days ago, cooldown TOPIC_COOLDOWN_DAYS) and slot 2
//                     is picked instead
//   * repeated hook   its opening sentence is what the demo writer's first draft opens with,
//                     so the caption check catches a recycled hook
//
// Nothing here is read when SHEET_ID is set.

const cfg = $('config').first().json;
const L = cfg.log_columns;

const day = (n) => new Date(Date.now() - n * 86400000).toISOString().slice(0, 10);
const at = (n, h) => new Date(Date.now() - n * 86400000 - h * 3600000).toISOString();

const row = (o) => {
  const r = {};
  for (const k of Object.keys(L)) r[L[k]] = o[k] === undefined ? '' : o[k];
  return r;
};

const hook = 'Most approval steps fail because nobody owns the decision.';

return [
  row({ date: day(2), slug: 'demo-earlier-post', slot: 0, status: 'awaiting', channel_id: 'demo',
    message_id: '1300000000000000001', caption_fp: '0badc0de', pillar: 'Engineering insight',
    hook: hook, note: 'delivered for approval (demo history)', at: at(2, 3) }),
  row({ date: day(2), slug: 'demo-earlier-post', slot: 0, status: 'posted', channel_id: 'demo',
    message_id: '1300000000000000001', reply_id: '1300000000000000002', caption_fp: '0badc0de',
    pillar: 'Engineering insight', hook: hook, urn: 'urn:li:share:7000000000000000001',
    note: 'by demo reviewer — "post" (demo history)', at: at(2, 2) })
].map((json) => ({ json }));

// Resolve today's state BEFORE anything is generated.
//
// A date is in exactly one of four states, and the LOG is what decides — never the presence
// of a file, a rendered image or a Discord message:
//
//   nothing yet        no posted row today, no open draft            -> draft it
//   awaiting approval  an OPEN draft (any day) that has not expired  -> silent, one is pending
//   posted             a `posted` row for today                      -> silent, done for the day
//   cancelled          today's draft was closed by `cancelled`       -> draft again
//
// "Open" is the rule in the shared log-state block below: an `awaiting` row that no later row
// closes. Counting every `awaiting` row ever written would make a cancelled day look pending
// forever, because the log is append-only and the original row never goes away.
//
// Two rules that must not be reintroduced:
//
//   * A rendered image is NOT evidence of a post. It is written at draft time.
//   * There is NO cascade rule. A run is silent because TODAY's state says so, and for no
//     other reason.
//
// Input: every row of the Log tab (or the demo log). Output: exactly one item, always.

// ---- log state (shared) -------------------------------------------------------------------
// Inlined by build.mjs into "resolve todays state" (01), "find the pending draft" and "is the
// weekly report due?" (02). The Log tab is append-only, so a row is never updated to say a
// draft is finished. Instead a later row CLOSES it, by carrying the same message id:
//
//   awaiting      opens a draft (one Discord message id)
//   posted        closes it — it is on the page
//   cancelled     closes it — a reviewer said no; 01 drafts again the same day
//   expired       closes it — nobody answered within APPROVAL_EXPIRES_HOURS
//   superseded    closes it — an edit was accepted and re-delivered as a new message
//   failed        closes it — LinkedIn refused it for a reason that will not fix itself
//
// and three statuses that annotate an open draft without closing it:
//
//   edit-refused  an edit failed the caption rules; the original is still open
//   alert         the LinkedIn token was rejected; the approval is still open
//   report        the weekly report went out (not about a draft at all)
//
// An open draft is an `awaiting` row that no later closing row names. Reading "awaiting" as
// "open" is what made a second day's draft look like a conflict with the first.

const CLOSING = ['posted', 'cancelled', 'expired', 'superseded', 'failed'];

function cleanRows(raw, L) {
  const norm = (v) => String(v === undefined || v === null ? '' : v).trim();
  return raw
    .filter((r) => r && (norm(r[L.date]) || norm(r[L.slug])))
    .map((r, i) => ({
      date: norm(r[L.date]),
      slug: norm(r[L.slug]),
      slot: Number(r[L.slot]) || 0,
      status: norm(r[L.status]).toLowerCase(),
      channel_id: norm(r[L.channel_id]),
      message_id: norm(r[L.message_id]),
      reply_id: norm(r[L.reply_id]),
      caption_fp: norm(r[L.caption_fp]),
      pillar: norm(r[L.pillar]),
      hook: norm(r[L.hook]),
      urn: norm(r[L.urn]),
      note: norm(r[L.note]),
      at: norm(r[L.at]),
      _i: i
    }));
}

function openDrafts(rows) {
  const closed = new Set(rows.filter((r) => CLOSING.includes(r.status) && r.message_id)
    .map((r) => r.message_id));
  return rows.filter((r) => r.status === 'awaiting' && !(r.message_id && closed.has(r.message_id)));
}

function ageHours(row) {
  const t = Date.parse(row.at);
  return isNaN(t) ? 0 : (Date.now() - t) / 3600000;
}

function daysBetween(a, b) {
  const x = Date.parse(a + 'T00:00:00Z');
  const y = Date.parse(b + 'T00:00:00Z');
  if (isNaN(x) || isNaN(y)) return Infinity;
  return Math.round(Math.abs(y - x) / 86400000);
}

// Everything that actually went out, newest first.
function postedHistory(rows) {
  return rows.filter((r) => r.status === 'posted')
    .map((r) => ({ date: r.date, slug: r.slug, slot: r.slot, pillar: r.pillar, hook: r.hook, urn: r.urn, at: r.at }))
    .sort((a, b) => (a.date < b.date ? 1 : a.date > b.date ? -1 : 0));
}

function recentHooks(history, today, days) {
  return history.filter((h) => h.hook && daysBetween(h.date, today) <= days)
    .map((h) => ({ hook: h.hook, slug: h.slug, date: h.date }));
}

// Local calendar date, weekday and hour in the configured timezone. Intl rather than
// toISOString: a job at 08:00 Singapore is still "yesterday" in UTC.
function localParts(date, tz) {
  const f = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'short',
    hour: '2-digit', hourCycle: 'h23'
  });
  const p = {};
  for (const part of f.formatToParts(date)) p[part.type] = part.value;
  const days = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 };
  return {
    date: p.year + '-' + p.month + '-' + p.day,
    weekday: days[p.weekday] || 0,
    weekday_name: p.weekday,
    hour: Number(p.hour) || 0
  };
}
// ---- end log state ------------------------------------------------------------------------
const cfg = $('config').first().json;
const L = cfg.log_columns;

const today = localParts(new Date(), cfg.timezone || 'UTC');
const rows = cleanRows(items.map((i) => i.json || {}), L);

const todays = rows.filter((r) => r.date === today.date);
const posted = todays.filter((r) => r.status === 'posted');
const cancelled = todays.filter((r) => r.status === 'cancelled');

const open = openDrafts(rows);
const live = open.filter((r) => ageHours(r) <= cfg.approval_expires_hours);
const stale = open.filter((r) => ageHours(r) > cfg.approval_expires_hours);

const history = postedHistory(rows);

let draftable = true;
let reason = '';

// The demo bank ignores PUBLISH_DAYS so a reviewer importing this on a Saturday still sees the
// whole draft path. It is forced into preview, so it cannot publish on any day.
if (!cfg.publish_days.includes(today.weekday) && !cfg.using_demo_bank) {
  draftable = false;
  reason = today.weekday_name + ' is not a publishing day (PUBLISH_DAYS is '
    + cfg.publish_days.join(', ') + ')';
} else if (posted.length >= cfg.daily_cap) {
  draftable = false;
  reason = 'already posted today: ' + (posted[0].slug || 'unknown slug');
} else if (live.length) {
  // Not an error. Someone has a draft in front of them; a second one is how two posts go out
  // on one day.
  draftable = false;
  reason = 'a draft is already awaiting approval: ' + (live[0].slug || 'unknown slug')
    + ' (message ' + (live[0].message_id || 'unknown') + ', open '
    + Math.round(ageHours(live[0])) + 'h)';
} else if (cancelled.length) {
  // Deliberately draftable. A cancelled draft means "a different post", not "no post today".
  reason = 'today was cancelled earlier — drafting again';
} else if (stale.length) {
  // Workflow 02 marks it expired on its next poll. It is not approvable any more, so it does
  // not block today.
  reason = 'the open draft for ' + stale[0].slug + ' is past APPROVAL_EXPIRES_HOURS and will be '
    + 'marked expired — drafting a fresh one';
}

return [{
  json: {
    _today: today.date,
    _weekday: today.weekday,
    _weekday_name: today.weekday_name,
    _draftable: draftable,
    _reason: reason,
    _posted_slugs: history.map((h) => h.slug).filter(Boolean),
    _posted_history: history.slice(0, 30),
    _recent_hooks: recentHooks(history, today.date, cfg.hook_lookback_days),
    _open_drafts: open.length,
    _log_rows: rows.length,
    _mode: cfg.mode
  }
}];

// Today is not a day to draft on. Not a failure — the state machine said so, and the
// reason travels with the run so the execution list reads as an answer rather than a gap.
//
// This is where 'already posted today', 'a draft is already awaiting approval' and
// 'not a publishing day' all land.
const cfg = $('config').first().json;
const s = $('resolve todays state').first().json;

return [{
  json: Object.assign({}, { _today: s._today, _weekday: s._weekday_name, _log_rows: s._log_rows }, {
    _stopped: 'silent',
    _mode: cfg.mode,
    _reason: '[SILENT] ' + (s._reason || 'nothing to do today'),
    _at: new Date().toISOString()
  })
}];

// Pick the one post that goes out today, and prove it is allowed to.
//
// The bank is in publish order. Today's post is the lowest-numbered slot still `ready` that
// has never been published — and then it has to survive three guards, all carried over from
// build.js in the design repo, because a bank that was correct when it was built can be
// reordered in a spreadsheet afterwards:
//
//   layout   no two posts within WINDOW_SLOTS slots share a layout
//   pillar   no two posts within WINDOW_SLOTS slots share an argument
//   Thursday a "Design process" post goes out on a Thursday, or not at all
//
// and two more measured in calendar days against what the LOG says was actually published,
// which still hold after the bank is reordered or a post goes out by hand:
//
//   cooldown the same pillar is not published again within TOPIC_COOLDOWN_DAYS
//   family   at most FAMILY_MAX_PER_WEEK posts from one pillar family in any rolling 7 days
//
// It also decides WHO writes the caption: the bank cell if it has one, else the model, else
// (demo bank only) the demo writer, else nobody and the caption check holds it.
//
// A guard that trips HOLDS the post and moves to the next candidate. It never rewrites the
// bank and never silently publishes anyway — the reason travels with the run and ends up in
// the log, so a held post is visible rather than mysteriously skipped.
//
// Input: every row of the Bank tab, or nothing at all when SHEET_ID is blank.
// Output: exactly one item, always.

const cfg = $('config').first().json;
const state = $('resolve todays state').first().json;
const B = cfg.bank_columns;

const norm = (v) => String(v === undefined || v === null ? '' : v).trim();

// Items may arrive as a JSON string (from a sheet cell) or as a real array (demo bank).
function parseItems(v) {
  if (Array.isArray(v)) return v;
  const s = norm(v);
  if (!s) return [];
  try {
    const parsed = JSON.parse(s);
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return null;   // null means malformed, which is different from empty
  }
}

let bank;
if (cfg.using_demo_bank) {
  bank = cfg.demo_bank.map((p) => Object.assign({}, p, { state: 'ready', _row: 0 }));
} else {
  bank = items
    .map((i, n) => {
      const r = i.json || {};
      return {
        slot: Number(r[B.slot]) || 0,
        slug: norm(r[B.slug]),
        pillar: norm(r[B.pillar]),
        category: norm(r[B.category]),
        headline: norm(r[B.headline]),
        headline_size: Number(r[B.headline_size]) || 0,
        subhead: norm(r[B.subhead]),
        layout: norm(r[B.layout]).toLowerCase(),
        items: parseItems(r[B.items]),
        band: norm(r[B.band]),
        stat_big: norm(r[B.stat_big]),
        stat_sub: norm(r[B.stat_sub]),
        footer: norm(r[B.footer]),
        caption: String(r[B.caption] === undefined || r[B.caption] === null ? '' : r[B.caption]),
        state: norm(r[B.state]).toLowerCase(),
        _row: n + 2   // sheet row, for the reason string — row 1 is the headings
      };
    })
    .filter((p) => p.slug);
}

bank.sort((a, b) => a.slot - b.slot);

// ---------------------------------------------------------------- the three guards
const W = cfg.window_slots;
const designRe = new RegExp('^' + cfg.design_pillar_prefix.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));

function guards(p) {
  const held = [];

  // Layout and pillar, measured against every neighbour inside the window — published or
  // not. What matters is what a reader sees inside a week, so a row still sitting `ready`
  // two slots away still counts.
  for (const q of bank) {
    if (q.slug === p.slug) continue;
    if (Math.abs(q.slot - p.slot) >= W) continue;
    if (q.layout && q.layout === p.layout) {
      held.push('layout "' + p.layout + '" repeats: slot ' + p.slot + ' and slot ' + q.slot
        + ' (' + q.slug + ') are only ' + Math.abs(q.slot - p.slot) + ' apart, window is ' + W);
    }
    if (q.pillar && q.pillar === p.pillar) {
      held.push('pillar "' + p.pillar + '" repeats: slot ' + p.slot + ' and slot ' + q.slot
        + ' (' + q.slug + ') are only ' + Math.abs(q.slot - p.slot) + ' apart, window is ' + W);
    }
  }

  // Thursday. build.js derives the weekday from the slot number because at build time there
  // is no date; here there is a real one, so this checks the actual day.
  if (cfg.enforce_design_thursday && designRe.test(p.pillar)
      && state._weekday !== 4
      && !cfg.off_cadence_design_slots.includes(p.slot)) {
    held.push('pillar "' + p.pillar + '" goes out on Thursdays. Today is '
      + state._weekday_name + '. Move the slot, or add ' + p.slot
      + ' to OFF_CADENCE_DESIGN_SLOTS with a reason.');
  }

  // Structural: a row that cannot be rendered is held, not rendered wrong.
  const LAYOUTS = ['timeline', 'cards', 'grid', 'split', 'stat', 'stack'];
  if (!LAYOUTS.includes(p.layout)) {
    held.push('unknown layout "' + p.layout + '" — one of ' + LAYOUTS.join(', '));
  }
  if (p.items === null) {
    held.push('the Items cell is not valid JSON');
  } else if (p.layout !== 'stat' && (!p.items || !p.items.length)) {
    held.push('no items');
  }
  if (!p.headline) held.push('no headline');
  if (p.layout === 'grid' && !p.band) held.push('the grid layout needs a Band');
  if (p.layout === 'stat' && !p.stat_big) held.push('the stat layout needs a Stat big');

  // Rotation by date, from the log. The slot window above only knows the bank's order; this
  // knows what a follower actually saw and when.
  const family = (s) => String(s || '').split(',')[0].trim().toLowerCase();
  const history = state._posted_history || [];
  if (cfg.topic_cooldown_days > 0 && p.pillar) {
    const last = history.find((h) => h.pillar && h.pillar.toLowerCase() === p.pillar.toLowerCase());
    if (last) {
      const d = daysBetween(last.date, state._today);
      if (d < cfg.topic_cooldown_days) {
        held.push('pillar "' + p.pillar + '" was published ' + d + ' day(s) ago (' + last.slug
          + '); TOPIC_COOLDOWN_DAYS is ' + cfg.topic_cooldown_days);
      }
    }
  }
  if (cfg.family_max_per_week > 0 && p.pillar) {
    const week = history.filter((h) => h.pillar && family(h.pillar) === family(p.pillar)
      && daysBetween(h.date, state._today) < 7);
    if (week.length >= cfg.family_max_per_week) {
      held.push(week.length + ' "' + family(p.pillar) + '" posts in the last 7 days ('
        + week.map((h) => h.slug).join(', ') + '); FAMILY_MAX_PER_WEEK is '
        + cfg.family_max_per_week);
    }
  }

  return held;
}

function daysBetween(a, b) {
  const x = Date.parse(a + 'T00:00:00Z');
  const y = Date.parse(b + 'T00:00:00Z');
  if (isNaN(x) || isNaN(y)) return Infinity;
  return Math.round(Math.abs(y - x) / 86400000);
}

// ---------------------------------------------------------------- choose
const ready = bank.filter((p) =>
  cfg.ready_states.includes(p.state) && !state._posted_slugs.includes(p.slug));

const holds = [];
let chosen = null;

for (const p of ready) {
  const held = guards(p);
  if (!held.length) { chosen = p; break; }
  holds.push({ slot: p.slot, slug: p.slug, reasons: held });
}

if (!chosen) {
  return [{
    json: {
      _has_post: false,
      _today: state._today,
      _reason: ready.length
        ? 'every ready post is held: '
          + holds.map((h) => 'slot ' + h.slot + ' ' + h.slug + ' — ' + h.reasons[0]).join('; ')
        : 'the bank has no ready rows left — ' + bank.length + ' rows, '
          + state._posted_slugs.length + ' already published',
      _holds: holds,
      _bank_size: bank.length,
      _ready_size: ready.length
    }
  }];
}

// The caption decides the next branch. A row that already carries one is delivered as
// written; the model is only ever asked for a caption that does not exist yet.
const caption = chosen.caption.trim();
const writer = caption !== '' ? 'bank'
  : cfg.llm_enabled ? 'model'
  : cfg.using_demo_bank ? 'demo'
  : 'none';

// ---------------------------------------------------------------- the writing brief
// Built here rather than inside the HTTP node's body, so the rules the model is given are
// readable without opening a JSON blob. These are the caption rules from the
// house content guide, and they are checked again in code afterwards — a model
// asked for 220 words will sometimes write 340 and say it wrote 220.
const plain = (s) => String(s).replace(/<br\s*\/?>/gi, ' ').replace(/<[^>]+>/g, '').trim();

const system = [
  'You write LinkedIn captions for Your Company, a company that builds AI workflow automation',
  'and production systems for small and mid-sized businesses.',
  '',
  'Voice: specific, concrete, slightly understated. You are explaining something you have',
  'actually built to somebody who runs a business. Short sentences. No preamble.',
  '',
  'Hard rules:',
  '- ' + cfg.caption_min_words + '-' + cfg.caption_max_words + ' words, not counting hashtags.',
  '- Open with one specific point of view, not a definition and not a question.',
  '- Bullets only where they genuinely help scanning. Three to six if used.',
  '- Translate any technical detail into an operational, cost, risk, speed or maintenance',
  '  consequence. The reader does not care what the tool is called.',
  '- Include exactly one honest trade-off or limitation. Not a disclaimer — a real one.',
  '- Close with ONE easy-to-answer question or one specific invitation. Never two calls',
  '  to action.',
  '- End with ' + cfg.hashtags_min + '-' + cfg.hashtags_max + ' hashtags on the last line,',
  '  the last of which is #YourCompany. At most ' + cfg.max_emoji + ' emoji in the whole caption.',
  '- No links and no @mentions anywhere in the caption. Hashtags only on the last line.',
  '',
  'Never write: ' + cfg.banned_phrases.join(', ') + '.',
  'Never write a long throat-clearing intro, an invented urgency, or an unsupported superlative.',
  '',
  'NEVER INVENT: engagement numbers, client names, outcomes, prices, timelines, headcounts,',
  'certifications, partners or case studies. You have not been given any, so there are none',
  'to use. Write about the mechanism, not about results you cannot support.',
  '',
  'Return the caption text and nothing else. No preamble, no markdown headings, no quotes',
  'around it, no explanation of what you wrote.'
].join('\n');

const user = [
  'Write the caption for this post. The image is already designed and says the following —',
  'the caption must not simply repeat it, it should be what a person says underneath it.',
  '',
  'Category: ' + chosen.category,
  'Pillar: ' + chosen.pillar,
  'Headline on the image: ' + plain(chosen.headline),
  'Subhead on the image: ' + chosen.subhead,
  'Footer takeaway on the image: ' + chosen.footer,
  '',
  'The supporting items on the image:',
  (chosen.items || []).map((it) => '- ' + (Array.isArray(it) ? it.map(plain).join(' — ') : plain(it))).join('\n'),
  chosen.band ? '\nThe statement band on the image: ' + chosen.band : '',
  (state._recent_hooks || []).length
    ? '\nRecent posts opened like this. Do not open the same way:\n'
      + state._recent_hooks.slice(0, 8).map((h) => '- ' + h.hook).join('\n')
    : ''
].join('\n');

return [{
  json: Object.assign({}, chosen, {
    _has_post: true,
    _llm_system: system,
    _llm_user: user,
    _today: state._today,
    _weekday_name: state._weekday_name,
    _caption: caption,
    _needs_caption: caption === '',
    _writer: writer,
    _caption_source: writer,
    _attempt: 1,
    _holds: holds,
    _bank_size: bank.length,
    _ready_size: ready.length,
    _reason: holds.length
      ? 'chose slot ' + chosen.slot + ' after holding ' + holds.length + ' earlier row(s)'
      : 'chose slot ' + chosen.slot
  })
}];

// Nothing in the bank can go out today.
//
// Either every row is published, or every remaining row is held by the layout, pillar or
// Thursday guard. Both are worth seeing: the first means somebody needs to write more
// posts, the second means the bank's ordering has drifted and needs a reshuffle rather
// than more content. `_holds` says which, per row.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: Object.assign({}, { _holds: s._holds, _bank_size: s._bank_size, _ready_size: s._ready_size }, {
    _stopped: 'bank exhausted',
    _mode: cfg.mode,
    _reason: '[HELD] ' + s._reason,
    _at: new Date().toISOString()
  })
}];

// DEMO ONLY — stands in for "[cred] LLM - write the caption" when the demo bank is in use and no
// LLM_API_KEY is set. It is reached only through the "demo" output of "who writes the caption?",
// which pick todays post selects only while SHEET_ID is blank.
//
// It answers in the same OpenAI-compatible shape as the real call, so "apply the caption" runs
// unchanged. The answer is deliberately the kind of first draft a model really produces, and it
// breaks four rules at once:
//
//   * it opens with the same hook as a post published two days ago (see "load the demo log")
//   * it carries a link in the body
//   * it uses a banned phrase
//   * it has eight hashtags
//
// so the execution shows the check catching each one and the rewrite fixing them.

const content = [
  'Most approval steps fail because nobody owns the decision!',
  '',
  'A workflow that drafts a post and then approves it itself has not added a review step. It has added a delay. The draft goes in, the same system reads it back, and nothing about the outcome depends on a person.',
  '',
  'This is a game-changer for teams that publish every day: the only approval that counts is a human, in a channel made for nothing else, typing a word that cannot be mistaken for chat. Its own message does not count. Another bot does not count. Silence does not count, and neither does a thumbs-up.',
  '',
  'The cost is a few minutes of somebody\'s morning, every morning. We think that is the right price for a company page.',
  '',
  'Full checklist here: https://example.com/approval-checklist',
  '',
  'Who approves what goes out on your page?',
  '',
  '#Automation #AI #Guardrails #Approval #Workflow #LinkedIn #Content #Demo'
].join('\n');

return [{
  json: {
    id: 'demo-first-draft',
    model: 'demo-writer',
    choices: [{ index: 0, finish_reason: 'stop', message: { role: 'assistant', content: content } }]
  }
}];

// Take whichever caption we ended up with and check it against the rules.
//
// Four writers reach this node, and every one is checked identically:
//
//   bank   the row's Caption cell, written by a person
//   model  the LLM's answer (OpenAI-compatible response in $json)
//   demo   the demo writer's canned answer, same shape as the model's (demo bank only)
//   none   no caption and nobody configured to write one -> held with that reason
//
// The rules are the shared block below: length, hashtag count and placement, emoji, banned
// phrases, no links, no @mentions, and an opening line that does not repeat a hook published
// in the last HOOK_LOOKBACK_DAYS. A caption that fails is NEVER trimmed to fit. A model or
// demo caption gets one rewrite with these exact failures fed back ("rewrite allowed?"); a
// banked caption is held for the person who wrote it.

// ---- caption rules (shared) ---------------------------------------------------------------
// Inlined by build.mjs into every node that judges a caption: "apply the caption", "check the
// rewrite" (workflow 01) and "check the edited caption" (workflow 02). One copy of the rules,
// so a caption the model wrote, a caption the model rewrote and a caption a human typed into
// Discord are held to exactly the same standard.

// FNV-1a. Not a security hash — it lets workflow 02 prove that the caption it is about to
// publish is the one that was approved. require('crypto') needs NODE_FUNCTION_ALLOW_BUILTIN on
// the host, which is the kind of host setting the config rule exists to avoid depending on.
function fingerprint(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return ('0000000' + h.toString(16)).slice(-8);
}

// LinkedIn "little text" reserved characters. '#' is deliberately NOT escaped so hashtags keep
// working; everything else in the reserved set gets a backslash at publish time.
function escapeLittleText(s) {
  const RESERVED = '\\|{}@[]()<>*_~';
  return String(s).split('').map((c) => (RESERVED.includes(c) ? '\\' + c : c)).join('');
}

// A model sometimes wraps its answer in a code fence or in quotes despite being told not to.
// Unwrapping is lossless; anything beyond that would be editing, which no node here does.
function unwrapCaption(s) {
  return String(s || '')
    .replace(/^\s*```[a-z]*\s*\n?/i, '')
    .replace(/\n?```\s*$/i, '')
    .replace(/^\s*["“]([\s\S]+)["”]\s*$/, '$1')
    .trim();
}

// The hook is the opening sentence: what shows above "...see more" in the feed, and the part a
// follower remembers. Two posts that open the same way read as a template, however different
// the rest is.
function hookOf(caption) {
  const first = String(caption || '').split('\n').map((l) => l.trim()).find(Boolean) || '';
  const m = first.match(/^(.+?[.!?])(\s|$)/);
  return (m ? m[1] : first).slice(0, 200);
}

const HOOK_STOPWORDS = ['the', 'a', 'an', 'and', 'or', 'but', 'of', 'to', 'in', 'on', 'for',
  'is', 'are', 'was', 'it', 'its', 'that', 'this', 'with', 'you', 'your', 'we', 'our', 'not',
  'be', 'by', 'at', 'as', 'do', 'does'];

function hookWords(s) {
