// missing — an empty box passes a glance and reaches the page.
const logo = cfg.logo_present
  ? cfg.logo_svg.trim()
  : '<div class="logofallback">YOUR BRAND<span>&nbsp;/ logo not configured</span></div>';

// ---------------------------------------------------------------- the stylesheet
const css = `
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: ${cfg.canvas_width}px; height: ${cfg.canvas_height}px; }
  body {
    background: ${C.bg};
    font-family: ${C.font};
    -webkit-font-smoothing: antialiased;
    overflow: hidden;
  }
  .strip { position: absolute; left: 0; right: 0; bottom: 0; height: 13px; background: ${C.accent}; }
  .content {
    position: absolute; inset: 74px 74px 88px 74px;
    display: flex; flex-direction: column;
  }
  .head { display: flex; align-items: center; justify-content: space-between; }
  .logo svg { width: 306px; height: auto; display: block; }
  .cat { color: ${C.muted}; font-size: 19px; letter-spacing: 0.3em; font-weight: bold; }

  .headline {
    margin-top: 74px;
    font-size: ${Number(p.headline_size) || 94}px; line-height: 1.06; font-weight: bold;
    color: ${C.white}; letter-spacing: -0.015em;
  }
  .headline em { color: ${C.accent}; font-style: normal; }
  .subhead { margin-top: 30px; font-size: 30px; line-height: 1.4; color: ${C.muted}; max-width: 830px; }

  .timeline { display: flex; flex-direction: column; flex: 1; margin-top: 56px; }
  .titem { display: flex; gap: 30px; flex: 1; }
  .titem.last { flex: none; }
  .tcol { width: 58px; flex: none; display: flex; flex-direction: column; align-items: center; }
  .circle {
    width: 58px; height: 58px; border-radius: 50%; flex: none;
    border: 1px solid ${C.line}; color: ${C.white};
    font-size: 21px; font-weight: bold;
    display: flex; align-items: center; justify-content: center;
  }
  .circle.focal { background: ${C.accent}; border-color: ${C.accent}; }
  .tline { width: 1px; flex: 1; background: ${C.line}; }
  .tbody { padding-top: 4px; padding-bottom: 32px; }
  .ttitle { font-size: 35px; font-weight: bold; color: ${C.white}; }
  .ttitle.focal { color: ${C.accent}; }
  .tdesc { margin-top: 11px; font-size: 25px; color: ${C.muted}; }

  .cards { display: flex; gap: 26px; flex: 1; margin-top: 58px; }
  .card {
    flex: 1; display: flex; flex-direction: column;
    border: 1px solid ${C.card_border}; border-radius: 14px;
    background: ${C.card_bg}; padding: 34px 30px;
  }
  .card.focal { border-color: ${C.accent}; background: rgba(220, 32, 86, 0.07); }
  .ceyebrow { font-size: 17px; letter-spacing: 0.11em; font-weight: bold; color: ${C.muted}; }
  .ctitle { margin-top: 22px; font-size: 41px; line-height: 1.12; font-weight: bold; color: ${C.white}; }
  .ctitle.focal { color: ${C.accent}; }
  .cspacer { flex: 1; min-height: 40px; }
  .cdesc { font-size: 23px; line-height: 1.42; color: ${C.muted}; }

  .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; flex: 1; margin-top: 48px; }
  .gcell {
    border: 1px solid ${C.card_border}; border-radius: 14px; background: ${C.card_bg};
    padding: 30px 28px; display: flex; flex-direction: column;
  }
  .gx { font-size: 42px; line-height: 0.9; font-weight: bold; color: ${C.muted}; }
  .gtitle { margin-top: 18px; font-size: 32px; font-weight: bold; color: ${C.white}; }
  .gdesc { margin-top: 10px; font-size: 23px; line-height: 1.4; color: ${C.muted}; }
  .band {
    margin-top: 24px; background: ${C.accent}; border-radius: 14px;
    padding: 28px 30px; text-align: center;
    color: ${C.white}; font-size: 29px; font-weight: bold; letter-spacing: 0.01em;
  }

  .split { display: flex; gap: 26px; flex: 1; margin-top: 48px; }
  .scol {
    flex: 1; display: flex; flex-direction: column;
    border: 1px solid ${C.card_border}; border-radius: 14px;
    background: ${C.card_bg}; padding: 30px 28px;
  }
  .scol.focal { border-color: ${C.accent}; background: rgba(220, 32, 86, 0.07); }
  .shead { font-size: 19px; letter-spacing: 0.2em; font-weight: bold; color: ${C.muted}; }
  .scol.focal .shead { color: ${C.accent}; }
  .srows { display: flex; flex-direction: column; flex: 1; margin-top: 14px; }
  .srow {
    flex: 1; display: flex; align-items: center;
    font-size: 25px; line-height: 1.3; color: ${C.muted};
    border-bottom: 1px solid ${C.card_border};
  }
  .srow:last-child { border-bottom: none; }
  .scol.focal .srow { color: ${C.white}; }

  .statwrap {
    flex: 1; display: flex; flex-direction: column;
    align-items: center; justify-content: center; text-align: center;
  }
  .statbig { font-size: 260px; line-height: 0.86; font-weight: bold; color: ${C.accent}; letter-spacing: -0.04em; }
  .statsub { margin-top: 26px; font-size: 30px; line-height: 1.35; color: ${C.muted}; max-width: 640px; }
  .statcols { display: flex; gap: 26px; margin-top: 10px; }
  .scell {
    flex: 1; border: 1px solid ${C.card_border}; border-radius: 14px;
    background: ${C.card_bg}; padding: 26px 24px;
  }
  .scell.focal { border-color: ${C.accent}; background: rgba(220, 32, 86, 0.07); }
  .slabel { font-size: 19px; letter-spacing: 0.16em; font-weight: bold; color: ${C.white}; }
  .scell.focal .slabel { color: ${C.accent}; }
  .sdesc { margin-top: 12px; font-size: 22px; line-height: 1.4; color: ${C.muted}; }

  .stack { display: flex; flex-direction: column; gap: 16px; flex: 1; margin-top: 50px; }
  .bar {
    flex: 1; display: flex; align-items: center; gap: 30px;
    border: 1px solid ${C.card_border}; border-radius: 14px;
    background: ${C.card_bg}; padding: 0 30px;
  }
  .bar.focal { border-color: ${C.accent}; background: rgba(220, 32, 86, 0.07); }
  .blabel {
    width: 210px; flex: none;
    font-size: 20px; letter-spacing: 0.16em; font-weight: bold; color: ${C.muted};
  }
  .bar.focal .blabel { color: ${C.accent}; }
  .bdesc { font-size: 27px; line-height: 1.3; color: ${C.white}; }

  .foot {
    margin-top: 40px; padding-top: 28px; border-top: 1px solid ${C.line};
    display: flex; justify-content: space-between; align-items: baseline;
    font-size: 25px; font-weight: bold;
  }
  .foot .take { color: ${C.white}; }
  .foot .site { color: ${C.white}; }
`;

const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>${text(p.slug)}</title>
<style>${css}</style></head>
<body>
  <div class="content">
    <div class="head">
      <div class="logo">${logo}</div>
      <div class="cat">${text(p.category)}</div>
    </div>
    <div class="headline">${text(p.headline)}</div>
    <div class="subhead">${text(p.subhead)}</div>
${body(p)}
    <div class="foot"><span class="take">${text(p.footer)}</span><span class="site">${C.site}</span></div>
  </div>
  <div class="strip"></div>
</body></html>
`;

return [{
  json: Object.assign({}, p, {
    _html: html,
    _html_bytes: html.length,
    _reason: 'built the ' + p.layout + ' template, ' + html.length + ' bytes'
  })
}];

// Blocking layout check, run on the HTML before a pixel is rendered.
//
// This is the cheap half of what `validate_linkedin_layout.js` does in the earlier agent-based setup. It
// cannot see the rendered pixels — no browser here — so it checks the things that are
// decidable from the source, and the PNG check after the render covers the rest.
//
// Every rule here exists because the mistake it catches actually shipped. The two defects
// found on 2026-08-28 were both obvious in the image and invisible in the HTML, which is why
// the human still looks at the PNG in Discord: this node narrows what reaches them, it does
// not replace them.

const cfg = $('config').first().json;
const p = $json;
const html = p._html || '';
const C = cfg.brand;

const issues = [];
const warnings = [];

// ---------------------------------------------------------------- the accent, three zones
// DESIGN.md: the mark, one phrase in the headline, and the single focal element. A fourth
// zone reads as decoration and was the first round's most common mistake.
const emCount = (p.headline.match(/<em>/gi) || []).length;
if (emCount === 0) {
  warnings.push('no <em> in the headline — the accent phrase is one of the three zones the '
    + 'accent is allowed in, and this post gives it up');
} else if (emCount > 1) {
  issues.push(emCount + ' <em> phrases in the headline. One. Two accent lines out of three '
    + 'reads as shouting.');
}

// The focal class is applied to exactly one element per layout by the builder. If a bank row
// somehow produces none, the post has no focus at all.
// In the grid layout the accent band IS the focal element (it carries no `focal` class), so
// a grid with its band counts. Without this every grid row was held as a layout failure.
const focal = (html.match(/class="[^"]*\bfocal\b/g) || []).length
  + (p.layout === 'grid' && html.includes('class="band"') ? 1 : 0);
if (p.layout !== 'stat' && focal === 0) {
  issues.push('nothing carries the focal accent — the last item should');
}

// ---------------------------------------------------------------- the canvas
if (!html.includes('width: ' + cfg.canvas_width + 'px')
    || !html.includes('height: ' + cfg.canvas_height + 'px')) {
  issues.push('the canvas is not ' + cfg.canvas_width + 'x' + cfg.canvas_height);
}
if (!html.includes(C.bg)) issues.push('the background is not ' + C.bg);
if (html.includes('class="strip"') === false) issues.push('no brand strip');

// ---------------------------------------------------------------- nothing may be fetched
// The renderer loads this with no network. A linked stylesheet, font or image is a blank
// space in a published post, and it looks fine in a browser that has the file cached.
const external = html.match(/(?:src|href)\s*=\s*["'](?!data:|#)([^"']+)/gi) || [];
if (external.length) {
  issues.push('the template references ' + external.length + ' external resource(s): '
    + external.slice(0, 3).join(', ') + '. Everything must be inline — the renderer has no '
    + 'network.');
}
if (/@import|url\(\s*["']?https?:/i.test(html)) {
  issues.push('the stylesheet imports or fetches a remote resource');
}

// ---------------------------------------------------------------- the logo
if (!cfg.logo_present && !cfg.deliver_enabled) {
  // PREVIEW delivers nothing, so a placeholder wordmark cannot reach a reviewer. Say so, and
  // let the rest of the pipeline run so the preview is worth looking at.
  warnings.push('LOGO_SVG is blank. Fine in preview; it blocks the render the moment a draft '
    + 'would actually be delivered.');
} else if (!cfg.logo_present) {
  issues.push('LOGO_SVG is blank in config. The post would render with a text placeholder '
    + 'where the wordmark goes. Paste your_logo.svg into LOGO_SVG.');
} else if (!/<svg[\s>]/i.test(cfg.logo_svg)) {
  issues.push('LOGO_SVG does not contain an <svg> element — a truncated paste is the only '
    + 'way the logo goes missing');
}

// ---------------------------------------------------------------- text that will not fit
// The content box is 932px wide. Bold Arial caps run roughly 0.60em per character, so a line
// at the configured headline size has a character budget. Overrunning it wraps to an orphan
// word, which DESIGN.md says to fix by shortening the words, not the type.
const BOX = cfg.canvas_width - (74 * 2);
const size = Number(p.headline_size) || 94;
const budget = Math.floor(BOX / (size * 0.6));
const lines = String(p.headline).split(/<br\s*\/?>/i)
  .map((l) => l.replace(/<[^>]+>/g, '').trim());
for (const line of lines) {
  if (line.length > budget) {
    issues.push('headline line "' + line + '" is ' + line.length + ' characters at ' + size
      + 'px; about ' + budget + ' fit in the ' + BOX + 'px box. Shorten the words rather '
      + 'than the type.');
  }
}
if (lines.length > 4) {
  warnings.push('the headline is ' + lines.length + ' lines; DESIGN.md says two to four');
}

// ---------------------------------------------------------------- per-layout item counts
// Each layout is designed around a number of items. One more than it expects does not
// overflow — flexbox squeezes it — it just gets progressively unreadable, which is exactly
// the kind of thing that passes an HTML review and fails in the picture.
const EXPECTED = {
  timeline: [3, 4], cards: [3, 3], grid: [4, 4],
  split: [2, 2], stat: [3, 3], stack: [4, 5]
};
const range = EXPECTED[p.layout];
const n = (p.items || []).length;
if (range && (n < range[0] || n > range[1])) {
  issues.push('the ' + p.layout + ' layout takes ' + (range[0] === range[1] ? range[0]
    : range[0] + '-' + range[1]) + ' items, this row has ' + n);
}

// Empty strings inside an item are the other silent one: the cell renders, at full height,
// with nothing in it. That is the "dead void" defect from the first round.
(p.items || []).forEach((item, i) => {
  const parts = Array.isArray(item) ? item : [item];
  parts.forEach((part, j) => {
    if (Array.isArray(part)) {
      part.forEach((sub, k) => {
        if (!String(sub || '').trim()) {
          issues.push('item ' + (i + 1) + ' field ' + (j + 1) + '.' + (k + 1) + ' is empty');
        }
      });
    } else if (!String(part || '').trim()) {
      issues.push('item ' + (i + 1) + ' field ' + (j + 1) + ' is empty — it renders as a '
        + 'full-height blank');
    }
  });
});

if (!String(p.footer || '').trim()) issues.push('no footer takeaway');
if (!String(p.subhead || '').trim()) warnings.push('no subhead');
if (!String(p.category || '').trim()) issues.push('no category label');

return [{
  json: Object.assign({}, p, {
    _layout_ok: issues.length === 0,
    _issues: issues,
    _warnings: warnings,
    _reason: issues.length
      ? issues.length + ' layout issue(s): ' + issues[0]
      : 'layout ok' + (warnings.length ? ' with ' + warnings.length + ' warning(s)' : '')
  })
}];

// The template would not have rendered correctly, so it was not rendered.
//
// Fix the bank row — headline length, item count, an empty field — and run again. Every
// check that lands here corresponds to a defect that reached a published post once.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: Object.assign({}, { _slug: s.slug, _layout: s.layout, _issues: s._issues, _warnings: s._warnings }, {
    _stopped: 'layout failed',
    _mode: cfg.mode,
    _reason: '[HELD] ' + (s._issues || []).join('; '),
    _at: new Date().toISOString()
  })
}];

// No renderer, so no image, so no draft.
//
// This one deliberately does NOT degrade into delivering the caption on its own. A caption
// without its image is not a draft — a reviewer cannot approve what they cannot see, and
// an approval given against a missing image is an approval of whatever gets rendered later.
//
// Set RENDER_PROVIDER and RENDER_URL in config. Browserless next to n8n in the same
// docker-compose file is the shipped answer; README has the service block.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: Object.assign({}, { _slug: s.slug, _html_bytes: s._html_bytes }, {
    _stopped: 'renderer not configured',
    _mode: cfg.mode,
    _reason: '[BLOCKED] RENDER_PROVIDER or RENDER_URL is blank in config, so there is no way to turn '
    + 'the template into an image. The caption is written and the HTML is built — only the '
    + 'picture is missing.',
    _at: new Date().toISOString()
  })
}];

// Turn the HTML into one HTTP request, shaped for whichever renderer is configured.
//
// n8n has no browser. Every other step in this pipeline is local; this is the one call that
// has to go out, and it is worth keeping it swappable — the two providers below differ only
// in a URL, an auth header and where the bytes come back.
//
//   browserless   POST {RENDER_URL}/screenshot   -> the PNG bytes, in the response
//   hcti          POST https://hcti.io/v1/image  -> JSON { url }, downloaded in the next node
//
// Adding a third is this function plus a branch on the Switch. Do not add one that renders
// from a URL instead of from a body: the template is not hosted anywhere, and putting it
// somewhere fetchable to satisfy a renderer publishes an unapproved draft.

const cfg = $('config').first().json;
const p = $json;

const provider = cfg.render_provider;
let url = '';
let body = {};
let auth = '';

if (provider === 'browserless') {
  // The token is a query parameter, not a header. Browserless returns 401 with a bare body
  // when it is missing, which reads as a network problem rather than an auth one.
  url = cfg.render_url + '/screenshot' + (cfg.render_key ? '?token=' + encodeURIComponent(cfg.render_key) : '');
  body = {
    html: p._html,
    options: { type: 'png', fullPage: false, omitBackground: false },
    viewport: {
      width: cfg.canvas_width,
      height: cfg.canvas_height,
      deviceScaleFactor: cfg.device_scale
    },
    // The document has no web fonts and no images to wait for, so networkidle would just
    // add the timeout to every render. Fonts are the system stack by design.
    gotoOptions: { waitUntil: 'load' }
  };
} else if (provider === 'hcti') {
  url = 'https://hcti.io/v1/image';
  body = {
    html: p._html,
    viewport_width: cfg.canvas_width,
    viewport_height: cfg.canvas_height,
    device_scale: cfg.device_scale,
    ms_delay: 300
  };
  // Basic, user:key. btoa exists in the n8n Code sandbox; Buffer does not, reliably.
  auth = 'Basic ' + btoa(cfg.render_user + ':' + cfg.render_key);
}

return [{
  json: Object.assign({}, p, {
    _provider: provider,
    _render_url: url,
    _render_body: body,
    _render_auth: auth,
    _expect_bytes: provider === 'browserless',
    _reason: 'rendering ' + cfg.canvas_width + 'x' + cfg.canvas_height + ' at '
      + cfg.device_scale + 'x through ' + provider
  })
}];

// Confirm the renderer actually returned a picture, before a human is asked to look at it.
//
// A render can fail in three ways that all look like success to the HTTP node:
//
//   * the provider answers 200 with a JSON error body instead of bytes
//   * it answers with a real PNG that is a blank canvas — the template threw and the
//     screenshot caught an empty page
//   * it answers with something that is not a PNG at all (an HTML error page, a JPEG)
//
// So the bytes are checked rather than the status code. The PNG signature and the IHDR
// dimensions are in the first 24 bytes of the file and are read straight out of the header,
// which is also how render.sh in the design repo proved a render was not a stale file.

const cfg = $('config').first().json;
const post = $('build the render request').first().json;

const binary = $binary || {};
const key = Object.keys(binary)[0];
const problems = [];

let bytes = 0;
let width = 0;
let height = 0;
let mime = '';

if (!key) {
  problems.push('the renderer returned no binary data. Response: '
    + JSON.stringify($json).slice(0, 400));
} else {
  const b = binary[key];
  mime = b.mimeType || '';
  bytes = Number(b.fileSize) || 0;

  // n8n reports fileSize as a human string ("142 kB") on some versions, so measure the
  // buffer rather than trusting the field.
  const buf = await this.helpers.getBinaryDataBuffer(0, key);
  bytes = buf.length;

  const isPng = buf.length > 24
    && buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47;

  if (!isPng) {
    problems.push('what came back is not a PNG. First bytes: '
      + buf.slice(0, 16).toString('utf8').replace(/[^\x20-\x7e]/g, '.'));
  } else {
    // IHDR is always the first chunk: width at byte 16, height at 20, big-endian.
    width = buf.readUInt32BE(16);
    height = buf.readUInt32BE(20);

    const expectW = cfg.canvas_width * cfg.device_scale;
    const expectH = cfg.canvas_height * cfg.device_scale;
    if (width !== expectW || height !== expectH) {
      problems.push('the PNG is ' + width + 'x' + height + ', expected ' + expectW + 'x'
        + expectH + '. LinkedIn will letterbox anything that is not the 4:5 canvas.');
    }
    if (bytes < cfg.min_png_bytes) {
      problems.push('the PNG is only ' + bytes + ' bytes, under the ' + cfg.min_png_bytes
        + ' floor. A render this small is a blank or half-drawn canvas, not a post.');
    }
  }
}

return [{
  json: Object.assign({}, post, {
    _png_ok: problems.length === 0,
    _png_bytes: bytes,
    _png_width: width,
    _png_height: height,
    _png_mime: mime,
    _binary_key: key || '',
    _problems: problems,
    _reason: problems.length ? problems[0]
      : 'rendered ' + width + 'x' + height + ', ' + bytes + ' bytes'
  }),
  binary: binary
}];

// The renderer answered, but not with a usable picture.
//
// A failed render is a failure, not a reason to retry in a loop or to fall back to a
// generated image. An image model cannot be trusted with a logo, a headline or small body
// copy, which is the entire content of this canvas — so there is no fallback here on
// purpose. Escalate, fix the renderer, run again.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: Object.assign({}, { _slug: s.slug, _bytes: s._png_bytes, _dimensions: s._png_width + 'x' + s._png_height, _problems: s._problems }, {
    _stopped: 'no image',
    _mode: cfg.mode,
    _reason: '[FAILED] ' + (s._problems || []).join('; '),
    _at: new Date().toISOString()
  })
}];

// Build the message the reviewer sees, and nothing else.
//
// What leaves the system here is the caption and the image — the draft, exactly as it would
// be published. No internal paths, no slot numbers, no run ids, no reasoning about why this
// post was chosen. A reviewer approving a draft should be looking at the post, not at the
// workflow that made it.
//
// The caption travels in the message body rather than as an attached file so that what is
// read and what is published are the same string. If it will not fit in one Discord message
// the draft is HELD — never truncated. A caption cut at 2000 characters ends mid-sentence
// and still reads fine at the top, which is exactly how it gets approved.

const cfg = $('config').first().json;
const p = $json;

// The instruction is in config so workflow 02 strips exactly the same string back off.
const INSTRUCTION = cfg.approval_instruction;

// Discord counts UTF-16 code units, the same thing String.length counts.
const body = p._caption + '\n\n' + INSTRUCTION;
const overBy = body.length - cfg.discord_message_limit;

const problems = [];
if (overBy > 0) {
  problems.push('the caption plus the approval line is ' + body.length + ' characters, '
    + overBy + ' over Discord\'s ' + cfg.discord_message_limit + ' limit. Shorten the '
    + 'caption in the bank — it is not truncated here, because a caption cut mid-sentence '
    + 'still reads fine at the top and gets approved.');
}

return [{
  json: Object.assign({}, p, {
    _message: body,
    _message_length: body.length,
    _file_name: p._today + '_' + p.slug + '.png',
    _message_ok: problems.length === 0,
    _problems: problems,
    _reason: problems.length ? problems[0]
      : 'draft ready for ' + (cfg.test_delivery ? 'the TEST channel' : 'review') + ', '
        + body.length + ' characters and a ' + p._png_bytes + ' byte image'
  })
}];

// The caption will not fit in one Discord message, so the draft is held.
//
// Splitting it across two messages is worse than holding it: the watcher anchors on one
// message id, and a caption in two halves is one a reviewer approves having read the first.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: Object.assign({}, { _slug: s.slug, _length: s._message_length, _limit: cfg.discord_message_limit }, {
    _stopped: 'message too long',
    _mode: cfg.mode,
    _reason: '[HELD] ' + (s._problems || []).join('; '),
    _at: new Date().toISOString()
  })
}];

// PREVIEW mode. Everything was built and rendered; nothing left the building.
//
// This is the shipped default and the state a first run after import lands in. The draft
// exists in this execution — open the render node's output to look at the actual PNG,
// which is the point of previewing.
//
// To deliver to a test channel: set TEST_CHANNEL_ID. To go live: set TEST_RUN = false.
// Those are two separate acts, and only the second can ever publish.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: Object.assign({}, { _slug: s.slug, _caption_words: s._caption_words, _png_bytes: s._png_bytes, _png: s._png_width + 'x' + s._png_height }, {
    _stopped: 'preview - not delivered',
    _mode: cfg.mode,
    _reason: cfg.forced_preview
      ? '[PREVIEW] Forced into preview because the demo bank is in use (SHEET_ID is '
        + 'blank). Demo content can never reach the company page, whatever TEST_RUN says.'
      : '[PREVIEW] TEST_RUN is true and TEST_CHANNEL_ID is blank, so the draft was built '
        + 'and rendered but delivered nowhere.',
    _at: new Date().toISOString()
  })
}];

// The log row that makes tomorrow's run correct.
//
// This is the state machine's only write. It records that a draft was delivered and is now
// waiting on a human — `awaiting` — along with the Discord message id, which is how workflow
// 02 finds the reply, and the caption fingerprint, which is how it proves the thing it is
// about to publish is the thing that was approved.
//
// Written AFTER the Discord delivery succeeds, never before. A row that says a draft is
// awaiting approval when no draft was ever delivered silences tomorrow's run too, and
// nothing ever clears it.

const cfg = $('config').first().json;
const p = $('build the approval message').first().json;
const L = cfg.log_columns;

// The Discord node returns the created message. Its id is the one thing from this response
// that matters — it is the anchor workflow 02 scans forward from.
const sent = $json || {};
const messageId = String(sent.id || (sent.message && sent.message.id) || '');

const row = {};
row[L.date] = p._today;
row[L.slug] = p.slug;
row[L.slot] = p.slot;
row[L.status] = 'awaiting';
row[L.channel_id] = cfg.channel_id;
row[L.message_id] = messageId;
row[L.reply_id] = '';
row[L.caption_fp] = p._caption_fp;
row[L.pillar] = p.pillar || '';
row[L.hook] = p._hook || '';
row[L.urn] = '';
row[L.note] = 'delivered for approval in ' + cfg.mode + ' mode, ' + p._caption_words
  + ' words, caption from the ' + p._caption_source
  + (p._rewritten ? ' (rewritten once; fixed: ' + (p._fixed || []).join('; ').slice(0, 300) + ')' : '')
  + ', ' + p._png_bytes + ' byte image';
row[L.at] = new Date().toISOString();

return [{
  json: Object.assign(row, {
    _message_id: messageId,
    _delivered: messageId !== '',
    _reason: messageId
      ? 'logged slot ' + p.slot + ' as awaiting approval (message ' + messageId + ')'
      : 'Discord returned no message id — the draft may not have been delivered, so nothing '
        + 'is being marked as awaiting'
  })
}];

// SHEET_ID is blank, so there is no Log tab to append to.
//
// The row that WOULD have been written is the input to this node — open it to see exactly what
// the sheet would have gained. With a sheet configured this branch is never taken.
const cfg = $('config').first().json;
const rows = items.map((i) => i.json);

return [{
  json: {
    _stopped: 'demo - log row not written',
    _mode: cfg.mode,
    _would_write: rows,
    _status: rows.map((r) => r[cfg.log_columns.status]).join(', '),
    _slug: (rows[0] || {})[cfg.log_columns.slug] || '',
    _reason: '[DEMO] SHEET_ID is blank, so ' + rows.length + ' log row(s) were built but not '
      + 'written: ' + rows.map((r) => r[cfg.log_columns.status]).join(', '),
    _at: new Date().toISOString()
  }
}];

// One message per run that is worth a message, for the optional Slack webhook.
//
// Every path through both workflows arrives here, including the ones that did nothing, so a
// job that silently stopped drafting three weeks ago is noticed. But workflow 02 polls every
// five minutes, and almost every poll ends "nothing awaiting" or "still awaiting approval" —
// posting those would bury the one message that matters under 280 that do not. Those are
// QUIET: visible in the execution list, not sent.
//
// The caption is NOT included. It goes to the approval channel and nowhere else — a draft
// that reaches a second audience before it is approved has left the approval gate behind.

const cfg = $('config').first().json;
const s = $json;

const stopped = s._stopped || '';
const outcome = s._outcome || '';
const status = s._status || '';

const QUIET = ['nothing awaiting', 'still awaiting approval', 'LinkedIn alert already sent'];

const icon = outcome === 'POSTED' ? ':white_check_mark:'
  : s._token_problem ? ':rotating_light:'
  : outcome === 'FAILED' || outcome === 'UNKNOWN' || stopped === 'no image' ? ':x:'
  : stopped === 'caption held' || stopped === 'log conflict' ? ':warning:'
  : ':information_source:';

const headline = outcome === 'POSTED'
  ? 'Published: ' + (s._slug || 'unknown')
  : s._token_problem
    ? 'LinkedIn rejected the token — approved draft waiting: ' + (s._slug || 'unknown')
    : stopped
      ? 'No post: ' + stopped
      : status
        ? 'Draft ' + (s._slug || s.Slug || '') + ' ' + status
        : 'Draft delivered for approval: ' + (s.slug || s._slug || 'unknown');

// The early warning for the failure that has actually happened: a 60-day token lapsing on a
// weekend with nothing to say so.
const warnings = (s._warnings || []).slice();
const left = cfg.linkedin_token_days_left;
if (left !== null && left !== undefined && left <= cfg.token_warn_days) {
  warnings.push(left < 0
    ? 'the LinkedIn token expired ' + (-left) + ' day(s) ago (LINKEDIN_TOKEN_EXPIRES_ON). '
      + 'Approved drafts will not publish until it is refreshed.'
    : 'the LinkedIn token expires in ' + left + ' day(s). Refresh it and update '
      + 'LINKEDIN_TOKEN_EXPIRES_ON.');
}

const lines = [
  icon + ' *LinkedIn daily* — ' + headline,
  '*Mode:* ' + cfg.mode + (cfg.forced_preview ? ' (forced — demo bank in use)' : ''),
  s._reason ? '*Why:* ' + s._reason : '',
  s._post_url ? '*Post:* ' + s._post_url : '',
  s._approver ? '*By:* ' + s._approver : '',
  warnings.length ? '*Warnings:* ' + warnings.join('; ') : ''
].filter(Boolean);

const text = lines.join('\n');
// The token warning rides on workflow 01's once-a-day summary; it does not un-quiet a poll.
const quiet = QUIET.includes(stopped);

return [{
  json: {
    _summary: text,
    _slack_body: { text: text },
    _notify: cfg.report_enabled && !quiet,
    _quiet: quiet,
    _outcome: outcome || stopped || status || 'delivered',
    _reason: s._reason || ''
  }
}];
